{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Edaravone, a 3-methyl-1-phenyl-5-pyrazolone structurally closest to the query pyrazolone, has an absolute oral bioavailability of 57% in humans, confirming that this scaffold is well absorbed and exceeds the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pirfenidone, a phenyl-methyl pyridinone sharing the N-phenyl and ring-methyl motif, is rapidly absorbed with high oral bioavailability in humans and nonclinical species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Clobazam, an N-phenyl heterocycle, has 87-100% oral bioavailability in humans, supporting high absorption for phenyl-substituted heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Sulphinpyrazone, a phenyl-containing heterocycle, showed 90% absolute oral bioavailability in human volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Mavacamten, a heterocyclic drug with a phenyl substituent, has at least 85% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Fenspiride, a nitrogen heterocycle with a phenyl-containing side chain, showed 90% absolute bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is antipyrine (1,5-dimethyl-2-phenyl-3-pyrazolone), a small lipophilic pyrazolone. All transferable experimental evidence, including the closest pyrazolone analogue edaravone (57% absolute F in humans) and multiple phenyl-substituted heterocycles with 71-100% oral bioavailability, supports F >= 20%. No evidence suggests poor absorption, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for antipyrine itself is present in the provided records.",
    "The closest analogue edaravone has moderate rather than complete oral bioavailability (57%), leaving some quantitative uncertainty.",
    "Morgan similarities are low (0.22-0.40), limiting the strength of direct structural transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

